def decision_making(grid):
    # Define movements and goal position
    movements = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    goal_pos = grid["goal"]

    # Find the start position of the agent
    for i in range(len(grid["grid"])):
        for j in range(len(grid["grid"][i])):
            if grid["grid"][i][j] == grid["start"]:
                start_pos = (i, j)

    # Initialize a queue with the initial state and explored set
    queue = [(start_pos[0], start_pos[1])]
    explored = set((start_pos[0], start_pos[1]))

    while True:
        current_state = queue.pop(0)

        # If the goal is reached, return the path
        if current_state == goal_pos:
            path = [current_state]
            while current_state != start_pos:
                for movement in movements:
                    new_state = (current_state[0] + movement[0], current_state[1] + movement[1])
                    if new_state not in explored and 0 <= new_state[0] < len(grid["grid"]) and 0 <= new_state[1] < len(grid["grid"][new_state[0]]) and grid["grid"][new_state[0]][new_state[1]] != "X":
                        current_state = new_state
                        path.insert(0, current_state)
                        break
            return path

        # Add unvisited neighbors to the queue
        for movement in movements:
            new_state = (current_state[0] + movement[0], current_state[1] + movement[1])
            if 0 <= new_state[0] < len(grid["grid"]) and 0 <= new_state[1] < len(grid["grid"][new_state[0]]) and grid["grid"][new_state[0]][new_state[1]] != "X" and new_state not in explored:
                queue.append(new_state)
                explored.add(new_state)

