def get_neighbors(grid, cell):
    neighbors = []

    x, y = cell

    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        new_x, new_y = x + dx, y + dy

        if is_valid_move(grid, new_x, new_y) and grid[new_x][new_y] != 'X':
            neighbors.append((new_x, new_y))

    return neighbors

